pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount) public {
        // Ensure the target is not the contract itself and amount > 0
        vm.assume(target != address(c));
        vm.assume(amount > 0);

        // We need an adversarial target that does NOT revert on receiving ETH
        // but does NOT change the behavior that distinguishes the bug.
        // Actually, the bug is about ACCESS CONTROL, not about failing calls.
        // So any target that accepts ETH works. An EOA (fuzzed address) always accepts ETH.
        // However, to observe the difference we need to check if a NON-OWNER can send.
        // In P: non-owner sendMoney REVERTS. In M: non-owner sendMoney SUCCEEDS.
        // So we can assert that a non-owner call always REVERTS.
        // We use try/catch to catch the revert.
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference should always revert (ok == false), mutant may succeed (ok == true) for some amount/target.
        assertTrue(!ok, "Non-owner sendMoney must revert");
    }
}

