import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 sendAmount, uint256 sendCount) public {
        // restrict to feasible values
        vm.assume(initialDeposit > 0 && initialDeposit <= type(uint96).max);
        vm.assume(sendCount <= 10);
        vm.assume(sendAmount <= initialDeposit / (sendCount + 1));

        // fund the contract
        vm.deal(address(this), initialDeposit);
        (bool sent,) = address(c).call{value: initialDeposit}("");
        require(sent, "initial deposit failed");

        uint256 balanceBefore = address(c).balance;

        // simulate sendMoney calls to spend part of the balance
        for (uint256 i = 0; i < sendCount; i++) {
            if (address(c).balance >= sendAmount) {
                address target = address(uint160(uint256(keccak256(abi.encodePacked(i, block.timestamp)))));
                vm.prank(c.owner());
                c.sendMoney(target, sendAmount);
            }
        }

        uint256 expectedRemaining = address(c).balance;

        // call withdrawAll as owner
        vm.prank(c.owner());
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        if (ok) {
            // after a successful withdrawAll, the remaining contract balance must equal the expected remaining amount
            assertTrue(address(c).balance == expectedRemaining);
        }
    }
}

